INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2813,1,'<h1>Название вашего дела</h1><p>Одна-две фразы: что вы делаете и чем полезны клиенту.</p><p><a href=\"#contacts\">Связаться</a></p>');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2813,2,'<h1>Назва вашої справи</h1><p>Одна-дві фрази: що ви робите і чим корисні клієнту.</p><p><a href=\"#contacts\">Зв’язатися</a></p>');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2814,1,'<h2>Услуги</h2><ul><li><strong>Первая услуга</strong> Короткое описание: что получит клиент.</li><li><strong>Вторая услуга</strong> Короткое описание: что получит клиент.</li><li><strong>Третья услуга</strong> Короткое описание: что получит клиент.</li></ul>');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2814,2,'<h2>Послуги</h2><ul><li><strong>Перша послуга</strong> Короткий опис: що отримає клієнт.</li><li><strong>Друга послуга</strong> Короткий опис: що отримає клієнт.</li><li><strong>Третя послуга</strong> Короткий опис: що отримає клієнт.</li></ul>');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2815,1,'<h2>Цены</h2><ul><li><h3>Базовый</h3><p>1 000 ₽</p><ul><li>Что входит</li><li>Что входит</li></ul><p><a href=\"#contacts\">Выбрать</a></p></li><li><h3>Расширенный</h3><p>2 000 ₽</p><ul><li>Что входит</li><li>Что входит</li></ul><p><a href=\"#contacts\">Выбрать</a></p></li></ul>');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2815,2,'<h2>Ціни</h2><ul><li><h3>Базовий</h3><p>1 000 ₴</p><ul><li>Що входить</li><li>Що входить</li></ul><p><a href=\"#contacts\">Замовити</a></p></li><li><h3>Розширений</h3><p>2 000 ₴</p><ul><li>Що входить</li><li>Що входить</li></ul><p><a href=\"#contacts\">Замовити</a></p></li></ul>');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2816,1,'<h2>Отзывы</h2><blockquote><p>Текст отзыва клиента.</p><cite>Имя клиента</cite></blockquote><blockquote><p>Текст отзыва клиента.</p><cite>Имя клиента</cite></blockquote>');
