INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2825,1,'Ссылки в текстах страниц, которые ведут на несуществующие или отключённые страницы и отсутствующие файлы. Внешние сайты не проверяются. Исправьте ссылку в тексте страницы в режиме редактирования.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2825,2,'Посилання в текстах сторінок, що ведуть на неіснуючі або вимкнені сторінки та відсутні файли. Зовнішні сайти не перевіряються. Виправте посилання в тексті сторінки в режимі редагування.');
