INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2851,1,'Свойства страницы. «Название» — пункт меню и крошек; «Сегмент URI» — часть адреса; «Содержимое страницы» — шаблон (лендинг, услуга, контакты, текст). Вкладки языков — тексты на каждом языке. Сохраните кнопкой «Сохранить»; тексты самой страницы правятся на ней в режиме редактирования.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2851,2,'Властивості сторінки. «Назва» — пункт меню та крихт; «Сегмент URI» — частина адреси; «Вміст сторінки» — шаблон (лендінг, послуга, контакти, текст). Вкладки мов — тексти кожною мовою. Збережіть кнопкою «Зберегти»; тексти самої сторінки редагуються на ній у режимі редагування.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2852,1,'Новая страница. Заполните «Название» на каждом языке и «Сегмент URI» (латиница, цифры, дефис), выберите «Содержимое страницы» — шаблон. Пустые секции шаблона покажут пример текста в режиме редактирования.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2852,2,'Нова сторінка. Заповніть «Назву» кожною мовою та «Сегмент URI» (латиниця, цифри, дефіс), оберіть «Вміст сторінки» — шаблон. Порожні секції шаблону покажуть приклад тексту в режимі редагування.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2853,1,'Пользователи сайта. Строку выделяют щелчком; «Редактировать» открывает форму, «Активизировать» включает посетителя, зарегистрированного, но не подтвердившего адрес. Фильтр над таблицей ищет по колонке.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2853,2,'Користувачі сайту. Рядок виділяють клацанням; «Редагувати» відкриває форму, «Активувати» вмикає відвідувача, який зареєструвався, але не підтвердив адресу. Фільтр над таблицею шукає за колонкою.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2854,1,'Данные пользователя. E-mail — логин для входа; пароль меняется, только если ввести новый. На вкладке «Группы» — права: администратор видит админку.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2854,2,'Дані користувача. E-mail — логін для входу; пароль змінюється, лише якщо ввести новий. На вкладці «Групи» — права: адміністратор бачить адмінку.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2855,1,'Новый пользователь: e-mail (логин), пароль, имя; на вкладке «Группы» — права.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2855,2,'Новий користувач: e-mail (логін), пароль, імя; на вкладці «Групи» — права.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2856,1,'Файлы сайта: картинки и документы для текстов. Двойной щелчок открывает папку, «Добавить» загружает файл. Вставить картинку в текст — кнопка «Изображение» редактора на странице.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2856,2,'Файли сайту: зображення та документи для текстів. Подвійне клацання відкриває теку, «Додати» завантажує файл. Вставити зображення в текст — кнопка «Зображення» редактора на сторінці.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2857,1,'Подписи интерфейса на всех языках (кнопки, поля, сообщения). Найдите константу фильтром, «Редактировать» — поменять текст. Название константы менять не нужно.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2857,2,'Підписи інтерфейсу всіма мовами (кнопки, поля, повідомлення). Знайдіть константу фільтром, «Редагувати» — змінити текст. Назву константи змінювати не потрібно.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2858,1,'Настройки сайта: название, ключевые слова и описание для поисковиков по умолчанию, флажки robots (NOINDEX закрывает весь сайт от поисковиков).');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2858,2,'Налаштування сайту: назва, ключові слова та опис для пошуковиків за замовчуванням, прапорці robots (NOINDEX закриває весь сайт від пошуковиків).');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2859,1,'Шаблон письма: тема и текст. Слова в квадратных скобках ([user_name], [site_name] …) подставляются при отправке — их не удаляйте.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2859,2,'Шаблон листа: тема та текст. Слова у квадратних дужках ([user_name], [site_name] …) підставляються під час надсилання — їх не видаляйте.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2860,1,'Сначала удалите или перенесите подстраницы этой страницы.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2860,2,'Спочатку видаліть або перенесіть підсторінки цієї сторінки.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2861,1,'Это служебная страница сайта (вход, админка, карта сайта): её нельзя удалить.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2861,2,'Це службова сторінка сайту (вхід, адмінка, мапа сайту): її не можна видалити.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2862,1,'На эту страницу ссылаются тексты других страниц — ссылки станут битыми. Удалить всё равно? Страницы со ссылками:');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2862,2,'На цю сторінку посилаються тексти інших сторінок — посилання стануть битими. Все одно видалити? Сторінки з посиланнями:');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2866,1,'Нельзя удалить папку вместе с её содержимым одним выделением: снимите выделение со строки «..» и повторите.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2866,2,'Не можна видалити теку разом із її вмістом одним виділенням: зніміть виділення з рядка «..» і повторіть.');
