INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2888,1,'Язык по умолчанию нельзя закрыть от посетителей: сначала назначьте другой язык по умолчанию.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2888,2,'Мову за замовчуванням не можна закрити від відвідувачів: спочатку призначте іншу мову за замовчуванням.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2889,1,'Языки сайта. Новый язык можно готовить незаметно для посетителей: снимите отметку «Открыт посетителям» — его страницы увидят только редакторы, в переключателе языков его не будет. Когда тексты готовы, поставьте отметку снова.');
INSERT INTO `share_lang_tags_translation` (`ltag_id`, `lang_id`, `ltag_value_rtf`) VALUES (2889,2,'Мови сайту. Нову мову можна готувати непомітно для відвідувачів: зніміть позначку «Відкритий відвідувачам» — її сторінки побачать лише редактори, у перемикачі мов її не буде. Коли тексти готові, поставте позначку знову.');
INSERT INTO `mail_templates` (`template_id`, `template_sysname`, `template_is_active`, `template_hints`) VALUES (1,'user_registration',1,'[user_name] - имя пользователя, [user_login] - логин (e-mail), [password_link] - ссылка установки пароля (действует час), [site_name] - название сайта, [site_url] - адрес сайта');
INSERT INTO `mail_templates` (`template_id`, `template_sysname`, `template_is_active`, `template_hints`) VALUES (2,'user_restore_password',1,'[sex_suffix_hello] - окончание обращения по полу пользователя (константы TXT_EMAIL_SUFFIX_SEX_M/F/UNKNOWN), [user_name] - имя, [user_login] - логин (e-mail), [restore_link] - ссылка для смены пароля (действует час), [site_name] - название сайта, [site_url] - адрес сайта');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (1,1,'Регистрация пользователя','Регистрация на сайте [site_name]','Здравствуйте, [user_name]!\n\nВы зарегистрированы на сайте [site_name] ([site_url]). Логин: [user_login]\n\nЗадайте пароль по ссылке (действует час): [password_link]\nЕсли ссылка устарела, воспользуйтесь «Забыли пароль?» на странице входа.\n\nПисьмо отправлено автоматически, отвечать на него не нужно.','<p>Здравствуйте, [user_name]!</p>\n<p>Вы зарегистрированы на сайте <a href=\"[site_url]\">[site_name]</a>. Логин: <strong>[user_login]</strong></p>\n<p><a href=\"[password_link]\">Задайте пароль</a> — ссылка действует час. Если она устарела, воспользуйтесь «Забыли пароль?» на странице входа.</p>\n<p>Письмо отправлено автоматически, отвечать на него не нужно.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (1,2,'Реєстрація користувача','Реєстрація на сайті [site_name]','Вітаємо, [user_name]!\n\nВи зареєстровані на сайті [site_name] ([site_url]). Логін: [user_login]\n\nЗадайте пароль за посиланням (діє годину): [password_link]\nЯкщо посилання застаріло, скористайтеся «Забули пароль?» на сторінці входу.\n\nЛист надіслано автоматично, відповідати на нього не потрібно.','<p>Вітаємо, [user_name]!</p>\n<p>Ви зареєстровані на сайті <a href=\"[site_url]\">[site_name]</a>. Логін: <strong>[user_login]</strong></p>\n<p><a href=\"[password_link]\">Задайте пароль</a> — посилання діє годину. Якщо воно застаріло, скористайтеся «Забули пароль?» на сторінці входу.</p>\n<p>Лист надіслано автоматично, відповідати на нього не потрібно.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (2,1,'Восстановление пароля','Смена пароля на сайте [site_name]','Уважаем[sex_suffix_hello] [user_name]!\n\nДля учётной записи [user_login] на сайте [site_name] ([site_url]) запрошена смена пароля.\nЧтобы задать новый пароль, перейдите по ссылке (она действует один час):\n[restore_link]\n\nЕсли вы не запрашивали смену пароля, просто проигнорируйте это письмо: пароль останется прежним.','<p>Уважаем[sex_suffix_hello] [user_name]!</p>\n<p>Для учётной записи [user_login] на сайте <a href=\"[site_url]\">[site_name]</a> запрошена смена пароля.</p>\n<p>Чтобы задать новый пароль, перейдите по ссылке (она действует один час):<br><a href=\"[restore_link]\">[restore_link]</a></p>\n<p>Если вы не запрашивали смену пароля, просто проигнорируйте это письмо: пароль останется прежним.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (2,2,'Відновлення пароля','Зміна пароля на сайті [site_name]','Шановн[sex_suffix_hello] [user_name]!\n\nДля облікового запису [user_login] на сайті [site_name] ([site_url]) запитано зміну пароля.\nЩоб задати новий пароль, перейдіть за посиланням (воно дійсне одну годину):\n[restore_link]\n\nЯкщо ви не запитували зміну пароля, просто проігноруйте цей лист: пароль залишиться попереднім.','<p>Шановн[sex_suffix_hello] [user_name]!</p>\n<p>Для облікового запису [user_login] на сайті <a href=\"[site_url]\">[site_name]</a> запитано зміну пароля.</p>\n<p>Щоб задати новий пароль, перейдіть за посиланням (воно дійсне одну годину):<br><a href=\"[restore_link]\">[restore_link]</a></p>\n<p>Якщо ви не запитували зміну пароля, просто проігноруйте цей лист: пароль залишиться попереднім.</p>');
